INSERT INTO `gewuerzerlebnisse` VALUES
(1,'Asiatische Gewürzreise',65.00,'Entdecke die Aromen Asiens mit exotischen Gewürzen aus Thailand, Vietnam und Indien','flavr. Studio Zürich',12,180,1),
(2,'Feurige Chili-Verkostung',45.00,'Von mild bis extrem scharf: Lerne verschiedene Chili-Sorten kennen und stelle deine eigene Chili-Mischung her','Kochschule Luzern',15,120,1),
(3,'Orientalischer Basar',75.00,'Tauche ein in die Welt von Ras el Hanout, Sumac und Zaatar. Wir bereiten traditionelle Gerichte aus dem Morgenland zu','Gourmet-Küche Bern',10,150,1),
(4,'Kräuterzauber aus den Alpen',55.00,'Entdecke heimische Kräuter und ihre Verwendung. Wanderung mit Kräutersammeln inklusive','Naturzentrum St. Gallen',8,240,1),
(5,'Weihnachtsbäckerei Gewürze',50.00,'Zimt, Nelken, Anis & Co. Lerne die traditionellen Weihnachtsgewürze kennen und backe gemeinsam Lebkuchen und Spekulatius','flavr. Studio Zürich',14,180,1),
(6,'Grill & BBQ Meisterkurs',70.00,'Perfekte Gewürzmischungen fürs Grillen. Lerne trocken Rubs, Marinaden und Saucen kennen. Inklusive Grillpraxis!','Gartenrestaurant Winterthur',12,210,1),
(7,'Gesunde Gewürzküche',60.00,'Wie Gewürze deine Gesundheit unterstützen können. Mit ayurvedischen und naturheilkundlichen Tipps für den Alltag','Wellness-Center Thalwil',16,150,1),
(8,'Sushi & Japanische Gewürze',80.00,'Wasabi, Shichimi Togarashi und mehr. Lerne japanische Gewürze kennen und rolle deine eigenen Sushi. Profi-Koch führt durch den Abend','Japanisches Restaurant Basel',10,180,1),
(9,'Schokolade & Gewürze',58.00,'Die perfekte Kombination: Edelschokolade mit Chili, Zimt, Kardamom und anderen Gewürzen. Schokoladenprobe inklusive','Schokoladen-Atelier Luzern',12,120,1),
(10,'Indische Curry-Nacht',68.00,'Garam Masala, Curryblätter und Co. Wir kochen verschiedene Currys und lernen die Geheimnisse der indischen Gewürzküche kennen','Indisches Restaurant Zürich',14,180,1);
/*!40000 ALTER TABLE `gewuerzerlebnisse` ENABLE KEYS */;
UNLOCK TABLES;
commit;

