DROP TABLE IF EXISTS `produkte`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `produkte` (
  `produkt_id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `beschreibung` text DEFAULT NULL,
  `preis_chf` decimal(10,2) NOT NULL,
  `herkunft` varchar(100) DEFAULT NULL,
  `menge` varchar(50) NOT NULL,
  `kategorie_id` int(11) DEFAULT NULL,
  `lagerbestand` int(11) DEFAULT 0,
  `aktiv` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`produkt_id`),
  KEY `kategorie_id` (`kategorie_id`),
  CONSTRAINT `produkte_ibfk_1` FOREIGN KEY (`kategorie_id`) REFERENCES `kategorien` (`kategorie_id`)
) ENGINE=InnoDB AUTO_INCREMENT=162 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

